candidates.contract_code:
pub assume_specification[ core::cmp::Ordering::is_eq ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (ordering == core::cmp::Ordering::Equal),
;

pub assume_specification[ core::cmp::Ordering::is_ge ](
    ordering: core::cmp::Ordering,
) -> (result: bool)
    ensures
        result == (
            ordering == core::cmp::Ordering::Equal
                || ordering == core::cmp::Ordering::Greater
        ),
;
